%[text] ## Lab 3
%[text] ### Harmonic response of second-order rectilinear systems
%%
%[text] #### Harware parameters
T = 0.001;  % sampling time (change to fit your experiment)
Fs = 1/T;   % Sampling Frequency

r = 0.01; % pinion gear radius [m]

Kt = 0.028; % torque constant for the EMB-AM2 actuator [Nm/A]

motor_eff = 1.0; % system efficiency (change to match your plant)

Kt = Kt*motor_eff; % including efficiency, actual Kt used in Simulink
%[text] #### Simulation Parameters
k_sim = 0;
b_sim = 0;
%%
%[text] ### Experiment 1: Sine-Sweep Tests
S = 15;             % simulation duration time

t = 0:T:S;          % total time
y = zeros(size(t)); % output
    
t1 = t(end);

f0 = 1;
f1 = 20;

amp = 1.6;

y = amp .* chirp(t, f0, t1, f1);
plot(t, y) %[output:0c418ce0]

% Add labels and title to the plot
xlabel('Time (s)'); %[output:0c418ce0]
ylabel('Output Amplitude'); %[output:0c418ce0]
title('Chirp Signal Response'); %[output:0c418ce0]
grid on; %[output:0c418ce0]


sim_input = timeseries(y', t');

% Define parameters
model_name = 'MSE_PLANT';

% Load and configure for Real-Time / External mode
load_system(model_name);
set_param(model_name, 'SimulationMode', 'external');

set_param(model_name, 'StopTime', num2str(S));

% Execute
set_param(model_name,'SimulationCommand','start')
%%
%% PLOTTING - Input Force

plot(rt_time, f_input,'LineWidth',2); %[output:43555573]
title('Input Force vs. Time'); %[output:43555573]
xlabel('Time [s]'); %[output:43555573]
ylabel('Force [N]'); %[output:43555573]
legend('Input Force'); %[output:43555573]
grid on; %[output:43555573]

%% PLOTTING - Position for both Carts
plot(rt_time, cart1_position*100, rt_time, cart2_position*100,'LineWidth',2); %[output:3a755322]
title('Position vs. Time'); %[output:3a755322]
xlabel('Time [s]'); %[output:3a755322]
ylabel('Position [cm]'); %[output:3a755322]
legend('Cart1','Cart2'); %[output:3a755322]
grid on; %[output:3a755322]

% plot(f_input, cart1_position, 'LineWidth', 2);
% title('Force vs displacement');
% xlabel('Force (N)')
% ylabel('displacement')
% grid on;

plot(rt_time, cart1_velocity*100, rt_time, cart2_velocity*100, 'LineWidth', 2); %[output:9aaf177b]
title('Velocity vs Time'); %[output:9aaf177b]
xlabel('Time [s]') %[output:9aaf177b]
ylabel('Velocity [cm/s]') %[output:9aaf177b]
grid on; %[output:9aaf177b]

%[text] ### FFT
Y = fft(f_input);
L = length(y);
f = Fs*(0:(L/2))/L;                     % Frequency vector for plotting
Y_half = Y(1:floor(L/2+1));                    % Single-sided spectrum
Y_half(2:end-1) = 2*Y_half(2:end-1);    % Adjust amplitude for single-sided spectrum

plot(f, abs(Y_half)); %[output:6d8d3692]
xlabel('Frequency (Hz)'); %[output:6d8d3692]
ylabel('Magnitude'); %[output:6d8d3692]
title('FFT of Input Force (Chirp Signal)'); %[output:6d8d3692]
grid on; %[output:6d8d3692]

xlim([f0 f1]) %[output:6d8d3692]
ylim([0 2000]) %[output:6d8d3692]

X = fft(cart1_position);
% Compute the frequency vector for the cart1_position FFT
f_cart1 = Fs*(0:(L/2))/L;                    
Y_cart1_half = X(1:floor(L/2+1));                    
Y_cart1_half(2:end-1) = 2*Y_cart1_half(2:end-1); 

plot(f_cart1, abs(Y_cart1_half)) %[output:3918f0ba]
xlabel('Frequency (Hz)'); %[output:3918f0ba]
ylabel('Magnitude'); %[output:3918f0ba]
title('FFT of cart position') %[output:3918f0ba]

xlim([f0 f1]) %[output:3918f0ba]


%%
%% 1. Force Column Vectors and Absolute Length Synchronization
% Force variables to be column vectors
cart1_position = cart1_position(:);
f_input        = f_input(:);

% Find the minimum length and force it to be even
L = min(length(cart1_position), length(f_input));
if mod(L, 2) ~= 0
    L = L - 1;
end

% Truncate both to the exact same matching length
cart1_position = cart1_position(1:L);
f_input        = f_input(1:L);

% Generate the correct frequency vector matching length L
f = Fs * (0:(L/2)) / L;
f = f(:);

%% 2. Compute Complex FFTs
F_input = fft(f_input);
X_output = fft(cart1_position);

% Extract single-sided complex spectra
F_half = F_input(1:L/2+1);
X_half = X_output(1:L/2+1);

% Scale amplitudes for single-sided spectrum
F_half(2:end-1) = 2 * F_half(2:end-1);
X_half(2:end-1) = 2 * X_half(2:end-1);

%% 3. Compute True Complex FRF
FRF = X_half ./ F_half; 

% Extract Magnitude and Phase
FRF_magnitude = abs(FRF);
FRF_phase     = rad2deg(angle(FRF)); 

figure; %[output:776b38eb]
plot(f, FRF_magnitude, 'LineWidth', 1.5); %[output:776b38eb]
title('FRF Magnitude'); %[output:776b38eb]
xlabel('Frequency (Hz)'); %[output:776b38eb]
ylabel('Magnitude'); %[output:776b38eb]
grid on; %[output:776b38eb]
xlim([f0 f1]); %[output:776b38eb]

plot(f, FRF_phase) %[output:44333bd1]
title('FRF Phase'); %[output:44333bd1]
xlabel('Frequency (Hz)'); %[output:44333bd1]
ylabel('Phase angle (deg)') %[output:44333bd1]
xlim([f0 f1]); %[output:44333bd1]

